<?php
declare(strict_types=1);
require __DIR__.'/nursing-worklist.php';
use App\Services\{WorkerJourneyService,CareService,Crypto};
$journeyUserId=$s->insert('users',['company_id'=>1,'role'=>'worker','name'=>'Trabalhadora da jornada fictícia','email'=>'journey@test.invalid','password_hash'=>'unused']);
$journeyUser=$s->one('SELECT * FROM users WHERE id=?',[$journeyUserId]);
$journeyPatient=$s->insert('patients',['company_id'=>1,'user_id'=>$journeyUserId,'name'=>'Trabalhadora fictícia']);
$s->insert('care_team_assignments',['company_id'=>1,'patient_id'=>$journeyPatient,'team_id'=>1]);
$journey=new WorkerJourneyService($s,$journeyUser);
verify($journey->sync()['points']===0 && $journey->view()['completed']===0,'Empty journey does not invent achievements');
foreach([$admin,$manager,$navigator,$doctor,$nurse,$dependent] as $actor) {
    denied(fn()=>(new WorkerJourneyService($s,$actor))->view(),403);
    denied(fn()=>(new WorkerJourneyService($s,$actor))->sync(),403);
}
$appointment=$s->insert('appointments',['company_id'=>1,'patient_id'=>$journeyPatient,'professional_id'=>1,'scheduled_at'=>date('Y-m-d H:i:s',time()+86400),'status'=>'expected']);
verify($journey->sync()['points']===10,'Scheduled appointment earns one recognition');
verify($journey->sync()['points']===10,'Refreshing cannot multiply points');
verify((int)$s->one('SELECT COUNT(*) n FROM worker_journey_awards WHERE patient_id=?',[$journeyPatient])['n']===1,'Award is persisted once');
$s->execute('UPDATE appointments SET status=? WHERE id=?',['cancelled',$appointment]);
verify($journey->sync()['points']===10,'Cancellation does not punish prior organization');
$second=$s->insert('appointments',['company_id'=>1,'patient_id'=>$journeyPatient,'professional_id'=>1,'scheduled_at'=>date('Y-m-d H:i:s',time()+2*86400),'status'=>'confirmed']);
verify($journey->sync()['points']===10,'Repeated booking and confirmation are not attendance or extra points');
$s->execute('UPDATE appointments SET status=? WHERE id=?',['attended',$second]);
verify($journey->sync()['points']===10,'Future attendance flags cannot earn attendance points');
$attendedAt=date('Y-m-d H:i:s',time()-3*86400);$s->execute('UPDATE appointments SET scheduled_at=? WHERE id=?',[$attendedAt,$second]);
verify($journey->sync()['points']===30,'Past professionally recorded attendance earns recognition');
$journeyCare=new CareService($s,$doctor);
$journeyPlan=$journeyCare->create(['patient_id'=>$journeyPatient,'professional_id'=>1,'team_id'=>1,'start_date'=>date('Y-m-d',time()-7*86400),'reassessment_date'=>date('Y-m-d',time()+86400),'objectives'=>'Acompanhamento fictício individualizado','interventions'=>'Orientação fictícia pactuada','status'=>'active','clinical_notes'=>'Não deve sair no DTO da jornada'])['id'];
$s->execute('UPDATE care_plans SET created_at=? WHERE id=?',[date('Y-m-d H:i:s',time()-7*86400),$journeyPlan]);
$journeyCare->adherence($journeyPlan,['action_description'=>'Relato fictício','source'=>'self_reported','completed'=>true,'occurred_at'=>date('Y-m-d H:i:s')]);
verify($journey->sync()['points']===30,'Self-report and merely having a plan do not prove follow-up');
$s->insert('clinical_evolutions',['plan_id'=>$journeyPlan,'author_id'=>1,'kind'=>'clinical','notes'=>Crypto::encrypt('Nota da própria consulta.'),'created_at'=>date('Y-m-d H:i:s',strtotime($attendedAt)+3600)]);
verify($journey->sync()['points']===30,'The consultation note on the same day is not a separate follow-up');
$followup=$s->insert('clinical_evolutions',['plan_id'=>$journeyPlan,'author_id'=>2,'kind'=>'nursing','notes'=>Crypto::encrypt('Acompanhamento confidencial fictício'),'created_at'=>date('Y-m-d H:i:s',time()-86400)]);
$full=$journey->sync();verify($full['points']===60 && $full['completed']===3 && $full['next_level']===null,'Documented later follow-up completes the three-step journey');
verify(!str_contains(json_encode($full),'confidencial') && !str_contains(json_encode($full),'source_id'),'Worker score exposes no clinical notes or evidence IDs');
$s->insert('care_plan_reviews',['plan_id'=>$journeyPlan,'author_id'=>1,'notes'=>Crypto::encrypt('Revisão fictícia'),'outcome'=>'active','created_at'=>date('Y-m-d H:i:s',time()-2*86400)]);
verify($journey->sync()['points']===60,'Review evidence reconciles without awarding twice');
verify($s->one('SELECT source_type FROM worker_journey_awards WHERE patient_id=? AND milestone=?',[$journeyPatient,'followup'])['source_type']==='review','A professional review can establish follow-up');
$s->execute('UPDATE appointments SET status=? WHERE id=?',['confirmed',$second]);
verify($journey->view()['points']===10,'Read does not claim awards whose source was corrected');
verify($journey->sync()['points']===10,'Evidence corrections are reconciled without false achievements');
$s->execute('UPDATE appointments SET status=? WHERE id=?',['attended',$second]);
verify($journey->sync()['points']===60,'Restored evidence restores existing awards');
verify((int)$s->one('SELECT COUNT(*) n FROM worker_journey_awards WHERE patient_id=?',[$journeyPatient])['n']===3,'Corrections never create duplicate awards');
$otherWorkerId=$s->insert('users',['company_id'=>2,'role'=>'worker','name'=>'Outro trabalhador','email'=>'otherjourney@test.invalid','password_hash'=>'unused']);
$s->insert('patients',['company_id'=>2,'user_id'=>$otherWorkerId,'name'=>'Outra pessoa fictícia']);
verify((new WorkerJourneyService($s,$s->one('SELECT * FROM users WHERE id=?',[$otherWorkerId])))->sync()['points']===0,'Other companies cannot borrow achievements');
$withoutPatient=$s->insert('users',['company_id'=>1,'role'=>'worker','name'=>'Sem cadastro','email'=>'emptyjourney@test.invalid','password_hash'=>'unused']);
verify(!(new WorkerJourneyService($s,$s->one('SELECT * FROM users WHERE id=?',[$withoutPatient])))->sync()['available'],'Missing patient relationship has no invented journey');
verify($s->one('SELECT id FROM audit_logs WHERE event=?',['journey_awarded'])!==null,'Achievements are audited');
echo "OK: {$count} combined journey/domain checks\n";
